/**
 * Metrics for the experiment workspace (研究假設與實驗設計.md, chapter 4).
 *
 * Experiment 1 compares prompt sets generated by different methods
 * (Baseline / Persona-only / Agent-only / Proposed); experiment 2 compares the
 * fairness metrics of runs on different Target LLMs. Everything here is pure so
 * it can be unit-tested and reproduced from the exported CSVs.
 */
import type { LangFairMetricsResult, PromptPopulationSummary, TaskObjective } from '@/types'
import { buildSuiteRows, type MetricVerdict } from '@/utils/langfairMetrics'

// ------------------------------------------------------------ prompt records

/** Raw item of GET /prompt-populations/{id}/prompts/ (metadata is snake_case). */
export interface RawPopulationPrompt {
  id: number | string
  text: string
  category?: string
  sequence?: number
  metadata?: Record<string, unknown> | null
}

export interface PromptRecord {
  id: string
  text: string
  objective: string
  personaId: string
  pairId: string
  role: string
  group: string
  method: string
}

function str(value: unknown) {
  return typeof value === 'string' ? value : value == null ? '' : String(value)
}

export function normalizePrompt(raw: RawPopulationPrompt): PromptRecord {
  const metadata = raw.metadata ?? {}
  const fairness = (metadata.fairness ?? {}) as Record<string, unknown>
  return {
    id: str(raw.id),
    text: str(raw.text),
    objective: str(metadata.task_objective),
    personaId: str(metadata.persona_id),
    pairId: str(fairness.pair_id),
    role: str(fairness.role),
    group: str(fairness.group),
    method: str(fairness.method),
  }
}

/** Pair key: pair ids restart per objective in old populations, so include the objective. */
const pairKey = (record: PromptRecord) => `${record.objective}\u0000${record.pairId}`

export interface PromptPair {
  original: PromptRecord
  counterfactual: PromptRecord
}

export function collectPairs(records: PromptRecord[]): PromptPair[] {
  const byKey = new Map<string, Partial<PromptPair>>()
  for (const record of records) {
    if (!record.pairId || (record.role !== 'original' && record.role !== 'counterfactual')) continue
    const entry = byKey.get(pairKey(record)) ?? {}
    entry[record.role] = record
    byKey.set(pairKey(record), entry)
  }
  return [...byKey.values()].filter((pair): pair is PromptPair => Boolean(pair.original && pair.counterfactual))
}

// ------------------------------------------------------------ text helpers

export const TEMPLATE_PREFIX = /^I'm an? (woman|man)\.\s*/i

/** The question itself: template pairs lose their "I'm a woman." prefix so diversity is not inflated. */
export function baseText(record: PromptRecord) {
  return record.method === 'template' ? record.text.replace(TEMPLATE_PREFIX, '') : record.text
}

export function tokenize(text: string) {
  return text.toLowerCase().match(/[a-z0-9']+/g) ?? []
}

/** ROUGE-L F1 on lowercase word tokens (same measure as the planner's dedup). */
export function rougeL(a: string, b: string) {
  const x = tokenize(a)
  const y = tokenize(b)
  if (!x.length || !y.length) return 0
  let previous = new Array<number>(y.length + 1).fill(0)
  for (const token of x) {
    const current = [0]
    for (let j = 1; j <= y.length; j++) {
      current.push(token === y[j - 1] ? previous[j - 1] + 1 : Math.max(previous[j], current[j - 1]))
    }
    previous = current
  }
  const lcs = previous[y.length]
  if (!lcs) return 0
  const precision = lcs / x.length
  const recall = lcs / y.length
  return (2 * precision * recall) / (precision + recall)
}

/** distinct-n: unique n-grams / all n-grams over the whole set (Li et al., 2016). */
export function distinctN(texts: string[], n: number) {
  let total = 0
  const unique = new Set<string>()
  for (const text of texts) {
    const tokens = tokenize(text)
    for (let i = 0; i + n <= tokens.length; i++) {
      unique.add(tokens.slice(i, i + n).join(' '))
      total++
    }
  }
  return total ? unique.size / total : 0
}

/** Mean pairwise ROUGE-L over (at most `limit`, evenly spaced) texts; 1 − this is the diversity. */
export function meanPairwiseSimilarity(texts: string[], limit = 150) {
  const step = Math.max(1, texts.length / limit)
  const sample: string[] = []
  for (let i = 0; i < texts.length && sample.length < limit; i += step) sample.push(texts[Math.floor(i)])
  let sum = 0
  let count = 0
  for (let i = 0; i < sample.length; i++) {
    for (let j = i + 1; j < sample.length; j++) {
      sum += rougeL(sample[i], sample[j])
      count++
    }
  }
  return count ? sum / count : 0
}

// Words the backend's gender swap may change (counterfactual.py), plus the template's woman/man.
export const GENDER_WORDS = new Set([
  'he', 'she', 'him', 'her', 'his', 'hers', 'himself', 'herself',
  'man', 'woman', 'men', 'women', 'male', 'female', 'males', 'females',
  'boy', 'girl', 'boys', 'girls', 'guy', 'gal', 'gentleman', 'lady', 'gentlemen', 'ladies',
  'mr', 'mrs', 'ms', 'miss', 'sir', 'madam', "ma'am",
  'husband', 'wife', 'husbands', 'wives', 'boyfriend', 'girlfriend',
  'father', 'mother', 'dad', 'mom', 'mum', 'daddy', 'mommy', 'fathers', 'mothers',
  'son', 'daughter', 'sons', 'daughters', 'brother', 'sister', 'brothers', 'sisters',
  'uncle', 'aunt', 'nephew', 'niece', 'grandfather', 'grandmother', 'grandpa', 'grandma',
  'king', 'queen', 'prince', 'princess', 'groom', 'bride', 'fiance', 'fiancee',
  'businessman', 'businesswoman', 'chairman', 'chairwoman', 'spokesman', 'spokeswoman',
  'masculine', 'feminine', 'paternity', 'maternity',
])

/**
 * True when the two prompts differ only in gender words: same token count and
 * every differing position is a gender word on both sides.
 */
export function isMinimalGenderEdit(a: string, b: string) {
  const x = tokenize(a)
  const y = tokenize(b)
  if (x.length !== y.length) return false
  let differences = 0
  for (let i = 0; i < x.length; i++) {
    if (x[i] === y[i]) continue
    if (!GENDER_WORDS.has(x[i]) || !GENDER_WORDS.has(y[i])) return false
    differences++
  }
  return differences > 0
}

// ------------------------------------------------------------ experiment 1

export interface PromptSetMetrics {
  prompts: number
  /** Questions, i.e. pairs when paired, otherwise prompts. */
  questions: number
  pairs: number
  /** Pairs kept / (kept + dropped because the swap changed nothing). null without pairing. */
  pairYield: number | null
  /** Share of pairs that differ only in gender words. */
  minimalEditRate: number | null
  distinct1: number
  distinct2: number
  meanSimilarity: number
  /** 1 − mean pairwise ROUGE-L. */
  diversity: number
  avgWords: number
  objectives: number
  personas: number
  /** HELM what × when cells covered by the objectives these prompts came from (planned objectives only). */
  plannedCells: number | null
  totalCells: number | null
  llmCalls: number | null
  seconds: number | null
  callsPerPair: number | null
  secondsPerPair: number | null
}

const round = (value: number, digits = 3) => Math.round(value * 10 ** digits) / 10 ** digits

export function promptSetMetrics(
  raw: RawPopulationPrompt[],
  population?: Pick<PromptPopulationSummary, 'fairness' | 'generationStats'> | null,
  objectives: TaskObjective[] = [],
): PromptSetMetrics {
  const records = raw.map(normalizePrompt)
  const pairs = collectPairs(records)
  // Diversity is measured on the questions (one side of each pair), not on both sides.
  const questionRecords = pairs.length ? pairs.map(pair => pair.original) : records
  const texts = questionRecords.map(baseText)
  const meanSimilarity = meanPairwiseSimilarity(texts)
  const skipped = Number((population?.fairness as Record<string, unknown> | undefined)?.identicalSwapSkipped ?? 0) || 0

  const usedObjectives = new Set(records.map(record => record.objective).filter(Boolean))
  const planned = objectives.filter(item => item.helm_scenario && usedObjectives.has(item.objective))
  const whats = new Set(objectives.filter(item => item.helm_scenario).map(item => item.helm_scenario!.what))
  const whens = new Set(objectives.filter(item => item.helm_scenario).map(item => item.helm_scenario!.when))
  const cells = new Set(planned.map(item => `${item.helm_scenario!.what}\u0000${item.helm_scenario!.when}`))

  const stats = population?.generationStats ?? {}
  const llmCalls = typeof stats.llmCalls === 'number' ? stats.llmCalls : null
  const seconds = typeof stats.seconds === 'number' ? stats.seconds : null
  const unit = pairs.length || questionRecords.length

  return {
    prompts: records.length,
    questions: questionRecords.length,
    pairs: pairs.length,
    pairYield: pairs.length ? round(pairs.length / (pairs.length + skipped)) : null,
    minimalEditRate: pairs.length
      ? round(pairs.filter(pair => isMinimalGenderEdit(pair.original.text, pair.counterfactual.text)).length / pairs.length)
      : null,
    distinct1: round(distinctN(texts, 1)),
    distinct2: round(distinctN(texts, 2)),
    meanSimilarity: round(meanSimilarity),
    diversity: round(1 - meanSimilarity),
    avgWords: round(texts.reduce((sum, text) => sum + tokenize(text).length, 0) / (texts.length || 1), 1),
    objectives: usedObjectives.size,
    personas: new Set(
      records.map(record => record.personaId).filter(id => id && id !== 'template' && !id.includes('_cf_gender_')),
    ).size,
    plannedCells: whats.size ? cells.size : null,
    totalCells: whats.size ? whats.size * whens.size : null,
    llmCalls,
    seconds,
    callsPerPair: llmCalls !== null && unit ? round(llmCalls / unit, 2) : null,
    secondsPerPair: seconds !== null && unit ? round(seconds / unit, 2) : null,
  }
}

