// ------------------------------------------------------------ experiment 2

export interface RunMetricCell {
  value: number
  ci: string
  verdict: MetricVerdict
  rule: string
}

export interface RunMetricRow {
  /** suite › metric path, identical across runs. */
  key: string
  suite: string
  label: string
  cells: Record<string, RunMetricCell | undefined>
}

/**
 * Pivot the headline metrics of several runs into rows keyed by metric path,
 * in first-seen order. Runs missing a metric simply have no cell.
 */
export function pivotRunMetrics(results: Record<string, LangFairMetricsResult | null | undefined>): RunMetricRow[] {
  const rows = new Map<string, RunMetricRow>()
  for (const [runId, result] of Object.entries(results)) {
    for (const suite of buildSuiteRows(result ?? null)) {
      for (const detail of suite.details) {
        if (!detail.headline) continue
        const key = `${suite.name} › ${detail.path}`
        let row = rows.get(key)
        if (!row) {
          row = { key, suite: suite.name, label: detail.label, cells: {} }
          rows.set(key, row)
        }
        row.cells[runId] = { value: detail.value, ci: detail.ci, verdict: detail.verdict, rule: detail.rule }
      }
    }
  }
  return [...rows.values()]
}

export function flaggedCount(rows: RunMetricRow[], runId: string) {
  return rows.filter(row => row.cells[runId]?.verdict === 'flagged').length
}
